#include <stdio.h>

int main() {
    // For
    for (int i = 0; i < 5; i++) {
        printf("%d ", i);
    }
    printf("\n");

    // While
    int n = 1;
    while (n < 100) n *= 2;
    printf("Première puissance de 2 >= 100 : %d\n", n);

    // Do-while
    int x;
    do {
        x = 42; // simulation d'une saisie
        printf("Valeur : %d\n", x);
    } while (x < 0);

    return 0;
}
